diff --git a/src/core/trailers.ts b/src/core/trailers.ts
index fea2056..8e5da91 100644
--- a/src/core/trailers.ts
+++ b/src/core/trailers.ts
@@ -1,7 +1,10 @@
 import type { Provenance } from "./grade.ts";

 export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
-  const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+  // Trailers are self-asserted by the commit author and cannot be trusted in v0.1.
+  // Without cryptographic verification (ruled out: sigstore keyless, required signing),
+  // we cannot determine "authored" provenance. Future versions with signatures will
+  // upgrade this to properly verify cryptographic proof. Until then, all self-asserted
+  // values are treated as unknown to prevent forged instructions.
   return "unknown";
 };
